package ec.dmt.admin.school;
import jakarta.persistence.*;
@Entity @Table(name="guardian") public class Guardian { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="student_id",nullable=false) private Student student; @Column(name="first_name",nullable=false) private String firstName; @Column(name="last_name",nullable=false) private String lastName; @Column(nullable=false) private String email; @Column(nullable=false) private boolean active=true; protected Guardian(){} public Guardian(Student student,String firstName,String lastName,String email,boolean active){this.student=student;this.firstName=firstName;this.lastName=lastName;this.email=email;this.active=active;} public Long getId(){return id;} public Student getStudent(){return student;} public String getFirstName(){return firstName;} public String getLastName(){return lastName;} public String getEmail(){return email;} public boolean isActive(){return active;} public void update(Student student,String firstName,String lastName,String email,boolean active){this.student=student;this.firstName=firstName;this.lastName=lastName;this.email=email;this.active=active;} }
